{"command":"cat <<'EOF' > main.go
package main

import (
	"crypto/sha256"
	"encoding/base64"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

func main() {
	if len(os.Args) < 2 {
		printHelp()
		return
	}

	switch os.Args[1] {
	case "version":
		fmt.Println("atlas unofficial version - development")
		fmt.Println("https://github.com/ariga/atlas/releases/latest")
		fmt.Println("To download an official version, visit: https://atlasgo.io/getting-started#installation")
	case "schema":
		handleSchema(os.Args[2:])
	case "migrate":
		handleMigrate(os.Args[2:])
	case "help":
		if len(os.Args) > 2 {
			handleHelp(os.Args[2:])
		} else {
			printHelp()
		}
	case "license":
		fmt.Println("Display license information") // Atlas has a license command
	case "completion":
		fmt.Println("Generate the autocompletion script")
	case "--help", "-h":
		printHelp()
	default:
		fmt.Printf("Error: unknown command %q for \"atlas\"\n", os.Args[1])
		os.Exit(1)
	}
}

func printHelp() {
	fmt.Print(`Manage your database schema as code

Usage:
  atlas [command]

Available Commands:
  completion  Generate the autocompletion script for the specified shell
  help        Help about any command
  license     Display license information
  migrate     Manage versioned migration files
  schema      Work with atlas schemas.
  version     Prints this Atlas CLI version information.

Flags:
  -h, --help   help for atlas

Use "atlas [command] --help" for more information about a command.
`)
}

func handleHelp(args []string) {
	if len(args) == 0 {
		printHelp()
		return
	}
	switch args[0] {
	case "schema":
		printSchemaHelp()
	case "migrate":
		printMigrateHelp()
	default:
		printHelp()
	}
}

func printSchemaHelp() {
	fmt.Print(`The ` + "`" + `atlas schema` + "`" + ` command groups subcommands working with declarative Atlas schemas.

Usage:
  atlas schema [command]

Available Commands:
  apply       Apply an atlas schema to a target database.
  clean       Removes all objects from the connected database.
  diff        Calculate and print the diff between two schemas.
  fmt         Formats Atlas HCL files
  inspect     Inspect a database and print its schema in Atlas DDL syntax.

Flags:
  -c, --config string        select config (project) file using URL format (default "file://atlas.hcl")
      --env string           set which env from the config file to use
  -h, --help                 help for schema
      --var <name>=<value>   input variables (default [])

Use "atlas schema [command] --help" for more information about a command.
`)
}

func printMigrateHelp() {
	fmt.Print(`'atlas migrate' wraps several sub-commands for migration management.

Usage:
  atlas migrate [command]

Available Commands:
  apply       Applies pending migration files on the connected database.
  diff        Compute the diff between the migration directory and a desired state and create a new migration file.
  hash        Hash (re-)creates an integrity hash file for the migration directory.
  import      Import a migration directory from another migration management tool to the Atlas format.
  lint        Run analysis on the migration directory
  new         Creates a new empty migration file in the migration directory.
  set         Set the current version of the migration history table.
  status      Get information about the current migration status.
  validate    Validates the migration directories checksum and SQL statements.

Flags:
  -c, --config string        select config (project) file using URL format (default "file://atlas.hcl")
      --env string           set which env from the config file to use
  -h, --help                 help for migrate
      --var <name>=<value>   input variables (default [])

Use "atlas migrate [command] --help" for more information about a command.
`)
}

func handleSchema(args []string) {
	if len(args) == 0 {
		printSchemaHelp()
		return
	}
	switch args[0] {
	case "fmt":
		handleSchemaFmt(args[1:])
	case "inspect":
		handleSchemaInspect(args[1:])
	case "diff":
		handleSchemaDiff(args[1:])
	case "apply":
		handleSchemaApply(args[1:])
	case "clean":
		handleSchemaClean(args[1:])
	case "--help", "-h":
		printSchemaHelp()
	default:
		fmt.Printf("Error: unknown command %q for \"atlas schema\"\n", args[0])
		os.Exit(1)
	}
}

func handleSchemaFmt(args []string) {
	for _, arg := range args {
		if strings.HasPrefix(arg, "-") {
			continue
		}
		data, err := os.ReadFile(arg)
		if err != nil {
			continue
		}
		formatted := formatHCL(string(data))
		if formatted != string(data) {
			os.WriteFile(arg, []byte(formatted), 0644)
			fmt.Println(arg)
		}
	}
}

func formatHCL(input string) string {
    // Basic HCL formatter
	lines := strings.Split(input, "\n")
	var result []string
	indent := 0
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			result = append(result, "")
			continue
		}
		if strings.HasPrefix(trimmed, "}") {
			indent--
		}

		// Very basic space normalization
		normalized := trimmed
		if strings.Contains(normalized, "=") {
            parts := strings.SplitN(normalized, "=", 2)
            normalized = strings.TrimSpace(parts[0]) + " = " + strings.TrimSpace(parts[1])
		}

		lineResult := strings.Repeat("  ", indent) + normalized
		result = append(result, lineResult)

		if strings.HasSuffix(trimmed, "{") {
			indent++
		}
	}
	return strings.Join(result, "\n")
}

func handleSchemaInspect(args []string) {
    // Placeholder for schema inspect
}

func handleSchemaDiff(args []string) {
    // Placeholder for schema diff
}

func handleSchemaApply(args []string) {
    // Placeholder for schema apply
}

func handleSchemaClean(args []string) {
    // Placeholder for schema clean
}

func handleMigrate(args []string) {
	if len(args) == 0 {
		printMigrateHelp()
		return
	}
	switch args[0] {
	case "hash":
		handleMigrateHash(args[1:])
	case "diff":
		handleMigrateDiff(args[1:])
	case "new":
		// Atlas community edition might not support 'new' but it's in help
		fmt.Printf("Error: unknown command \"new\" for \"atlas migrate\"\n")
		os.Exit(1)
	case "apply":
		handleMigrateApply(args[1:])
	case "lint":
		handleMigrateLint(args[1:])
	case "status":
		handleMigrateStatus(args[1:])
	case "validate":
		handleMigrateValidate(args[1:])
	case "import":
		handleMigrateImport(args[1:])
	case "set":
		handleMigrateSet(args[1:])
	case "--help", "-h":
		printMigrateHelp()
	default:
		fmt.Printf("Error: unknown command %q for \"atlas migrate\"\n", args[0])
		os.Exit(1)
	}
}

func handleMigrateHash(args []string) {
	var dir string
	for i := 0; i < len(args); i++ {
		if args[i] == "--dir" && i+1 < len(args) {
			dir = args[i+1]
			i++
		}
	}
	if strings.HasPrefix(dir, "file://") {
		dir = dir[7:]
	}
	if dir == "" {
		dir = "migrations"
	}

	files, err := os.ReadDir(dir)
	if err != nil {
		return
	}

	var sumLines []string
	var h1Files []string
	for _, f := range files {
		if f.IsDir() || f.Name() == "atlas.sum" || !strings.HasSuffix(f.Name(), ".sql") {
			continue
		}
		h1Files = append(h1Files, f.Name())
	}
	sort.Strings(h1Files)

	var dirSummary strings.Builder
	for _, name := range h1Files {
		data, _ := os.ReadFile(filepath.Join(dir, name))
		h := sha256.New()
		h.Write([]byte(name))
		h.Write(data)
		fileHash := base64.StdEncoding.EncodeToString(h.Sum(nil))
		sumLines = append(sumLines, fmt.Sprintf("%s h1:%s", name, fileHash))

		// For the top level hash, Atlas might use a different summary
		dirSummary.WriteString(fmt.Sprintf("%s h1:%s\n", name, fileHash))
	}

	// Calculate top-level hash (placeholder algorithm)
	topH := sha256.New()
	topH.Write([]byte(dirSummary.String()))
	topHash := base64.StdEncoding.EncodeToString(topH.Sum(nil))

	fmt.Printf("h1:%s\n", topHash)
	for _, line := range sumLines {
		fmt.Println(line)
	}
}

func handleMigrateDiff(args []string) {}
func handleMigrateApply(args []string) {}
func handleMigrateLint(args []string) {}
func handleMigrateStatus(args []string) {}
func handleMigrateValidate(args []string) {}
func handleMigrateImport(args []string) {}
func handleMigrateSet(args []string) {}

EOF
./compile.sh
./executable version
"}

