func formatHCL(input string) string {
	lines := strings.Split(input, "\n")
	var result []string
	indent := 0

	for i := 0; i < len(lines); i++ {
		line := strings.TrimSpace(lines[i])
		if line == "" {
			if i < len(lines)-1 {
				result = append(result, "")
			}
			continue
		}

		if strings.HasPrefix(line, "}") {
			indent--
		}

		if strings.HasSuffix(line, "{") {
			line = normalizeBlockHeader(line)
			result = append(result, strings.Repeat("  ", indent)+line)
			indent++
			continue
		}

		if strings.Contains(line, "=") {
			parts := strings.SplitN(line, "=", 2)
			key := strings.TrimSpace(parts[0])
			val := strings.TrimSpace(parts[1])
			result = append(result, strings.Repeat("  ", indent)+key+" = "+val)
		} else {
			result = append(result, strings.Repeat("  ", indent)+line)
		}
	}

	output := strings.Join(result, "\n")
	if !strings.HasSuffix(output, "\n") && len(output) > 0 {
		output += "\n"
	}
	return output
}

